		static const size_t VulkanDefaultShaderCount = 34;

		//! Returns the module compiled from the given source file name ("solid.frag"), or 0.
		inline const SVulkanDefaultShader* getVulkanDefaultShader(const char* name)
		{
			if (!name)
				return 0;
			for (size_t i = 0; i < VulkanDefaultShaderCount; ++i)
				if (strcmp(VulkanDefaultShaders[i].Name, name) == 0)
					return &VulkanDefaultShaders[i];
			return 0;
		}
